/// - w: real[1][16] (passed a plain number)
/// - n: int (passed a whole number)
/// - returns q: real[1][4] (passed a plain number)
/// - returns loss: real[1] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn quest(bv: [[f64; 3]; 16], rv: [[f64; 3]; 16], w: [f64; 16], n: i64) -> ([f64; 4], f64) {
    let mut q: [f64; 4] = [0.0; 4];
    let mut loss: f64 = 0.0;
    let mut bb: [[f64; 3]; 3] = [[0.0; 3]; 3];
    let mut ws: f64 = 0.0;
    {
        let __end67: i64 = n;
        let mut l: i64 = 0;
        while l < __end67 {
            let mut wl: f64 = w[(l) as usize];
            ws = (ws + wl);
            {
                let __end68: i64 = 3;
                let mut i: i64 = 0;
                while i < __end68 {
                    {
                        let __end69: i64 = 3;
                        let mut j: i64 = 0;
                        while j < __end69 {
                            bb[(i) as usize][(j) as usize] = (bb[(i) as usize][(j) as usize] + ((wl * bv[(l) as usize][(i) as usize]) * rv[(l) as usize][(j) as usize]));
                            j += 1;
                        }
                    }
                    i += 1;
                }
            }
            l += 1;
        }
    }
    let mut sg: f64 = ((bb[0][0] + bb[1][1]) + bb[2][2]);
    let mut z: [f64; 3] = [(bb[1][2] - bb[2][1]), (bb[2][0] - bb[0][2]), (bb[0][1] - bb[1][0])];
    let mut k: [[f64; 4]; 4] = [[0.0; 4]; 4];
    {
        let __end70: i64 = 3;
        let mut i: i64 = 0;
        while i < __end70 {
            {
                let __end71: i64 = 3;
                let mut j: i64 = 0;
                while j < __end71 {
                    k[(i) as usize][(j) as usize] = ((bb[(i) as usize][(j) as usize] + bb[(j) as usize][(i) as usize]) - (if (i == j) { sg } else { 0.0 }));
                    j += 1;
                }
            }
            k[(i) as usize][3] = z[(i) as usize];
            k[3][(i) as usize] = z[(i) as usize];
            i += 1;
        }
    }
    k[3][3] = sg;
    let (mut lam, mut v) = crate::alg::math::jacobi_eig4(k);
    let mut im: i64 = 0;
    {
        let __end72: i64 = 4;
        let mut i: i64 = 1;
        while i < __end72 {
            if (lam[(i) as usize] > lam[(im) as usize]) {
                im = i;
            }
            i += 1;
        }
    }
    q = crate::alg::math::qnorm([v[0][(im) as usize], v[1][(im) as usize], v[2][(im) as usize], v[3][(im) as usize]]);
    loss = (ws - lam[(im) as usize]);
    (q, loss)
}

/// A star-tracker attitude carried from t - lat to t with the gyro: q_st fromrotvec(w lat), unit.
/// - q_st: real[1][4] (passed a plain number)
/// - w: real[1][3] (passed a plain number)
/// - lat: real[1] (passed a plain number)
/// - returns q: real[1][4] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn latency(q_st: [f64; 4], w: [f64; 3], lat: f64) -> [f64; 4] {
    let mut q: [f64; 4] = [0.0; 4];
    q = crate::alg::math::qnorm(crate::alg::math::qmult(q_st, crate::alg::math::fromrotvec(rt::vscale(w, lat))));
    q
}
